// Enhanced random with timestamp seed
const seed = Date.now() + Math.random() * 1000;
const randomIndex = Math.floor(seed % items.length);
const selectedItem = items[randomIndex];

return [{ json: selectedItem.json }];

// Combine all RSS feeds
const allItems = $input.all();

// Filter for last 48 hours
const twoDaysAgo = new Date(Date.now() - 48 * 60 * 60 * 1000);
const recentItems = allItems.filter(item => {
  const pubDate = new Date(item.json.pubDate || item.json.published);
  return pubDate > twoDaysAgo;
});

// Score items by relevance to GFIN verticals
const keywords = [
  'grant', 'rfp', 'contract', 'funding', 
  'procurement', 'small business', 'nonprofit',
  'consulting', 'professional services', 'IT services'
];

const scoredItems = recentItems.map(item => {
  const text = `${item.json.title} ${item.json.description}`.toLowerCase();
  const score = keywords.reduce((sum, keyword) => 
    sum + (text.includes(keyword) ? 1 : 0), 0
  );
  return { ...item.json, relevanceScore: score };
});

// Sort by relevance and return top 5
scoredItems.sort((a, b) => b.relevanceScore - a.relevanceScore);
return scoredItems.slice(0, 5).map(item => ({ json: item }));

const items = $input.all();

for (const item of items) {
  const feedItem = item.json;
  let score = 0;

  // Skip if no title or link
  if (!feedItem.title || !feedItem.link) {
    item.json.relevanceScore = 0;
    continue;
  }

  // Score based on how recent
  const pubDate = new Date(feedItem.pubDate || feedItem.date);
  const now = new Date();
  const hoursOld = (now - pubDate) / (1000 * 60 * 60);

  if (hoursOld <= 24) score += 5;
  else if (hoursOld <= 48) score += 3;
  else score += 1;

  // Score based on keywords
  const title = (feedItem.title || '').toLowerCase();
  const description = (feedItem.description || '').toLowerCase();
  const content = title + ' ' + description;

  const keywords = [
    'grant', 'funding', 'rfp', 'contract', 'procurement',
    'small business', 'nonprofit', 'federal', 'opportunity',
    'million', 'billion'
  ];

  keywords.forEach(keyword => {
    if (content.includes(keyword)) score += 2;
  });

  // Add score to the item
  item.json.relevanceScore = score;
}

// Sort by score
items.sort((a, b) => (b.json.relevanceScore || 0) - (a.json.relevanceScore || 0));

// Return top 15
return items.slice(0, 15);

